// Import the Discord.js library
const { Client, Intents, Collection } = require('discord.js');

// Create a new Discord client
const client = new Client({ intents: [Intents.FLAGS.GUILDS, Intents.FLAGS.GUILD_MESSAGES] });

// Create a new collection for command handlers
const commands = new Collection();

// Define the ban command
const banCommand = {
  name: 'ban',
  description: 'Bans a user from the server',
  execute: async (message, args) => {
    // Get the user to ban
    const user = message.mentions.users.first();

    // Check if the user exists
    if (!user) {
      return message.reply('Please mention a user to ban.');
    }

    // Get the guild
    const guild = message.guild;

    // Check if the user is a member of the guild
    if (!guild.members.cache.has(user.id)) {
      return message.reply('That user is not in this server.');
    }

    // Ban the user
    await guild.members.ban(user);

    // Send a message to the channel
    message.channel.send(`Successfully banned ${user.tag}.`);
  }
};

// Add the ban command to the collection
commands.set(banCommand.name, banCommand);

// Define the client's event handlers
client.on('ready', () => {
  console.log(`Logged in as ${client.user.tag}`);
});

client.on('interactionCreate', async interaction => {
  // Check if the interaction is a command
  if (!interaction.isCommand()) {
    return;
  }

  // Get the command
  const command = commands.get(interaction.commandName);

  // Check if the command exists
  if (!command) {
    return;
  }

  // Execute the command
  try {
    await command.execute(interaction);
  } catch (error) {
    console.error(error);
    await interaction.reply('There was an error while executing that command.');
  }
});

// Login to Discord with the client's token
client.login('YOUR_TOKEN_HERE');
```

Note: Replace "YOUR_TOKEN_HERE" with your Discord bot's token.

